svg:
{# The company stamp, after the template the company drew: two arcs of text,
   three circles, a word in the middle, and the signer's strokes laid over
   it. What changes per person is the word and the phone; the company's
   name comes from the invoicing settings. The stamp fills the middle
   300×300 of the canvas; the 90 units around it are for strokes that run
   past the circle, so sheets size the image at 8/5 of the stamp they want. #}



  {# The strokes are stored in the template's blue; this paints them in the
     pen's colour, keeping only their shape. #}
















  <text font-size="{{ 21 if company|length <= 24 else (18 if company|length <= 30 else 15) }}" font-weight="bold" letter-spacing="1.5" stroke="none">
    {{ company }}



    ★  {% if phone %}Tel: {{ phone }}{% endif %}  ★


  <text x="150" y="{{ 132 if signature else 150 }}" dominant-baseline="central" font-size="{{ 34 if label|length <= 10 else (26 if label|length <= 14 else 20) }}" font-weight="bold" text-anchor="middle" stroke="none">{{ label }}


{% if signature %}
{# The strokes, under the word, in the lower half of the inner circle. #}

{% endif %}
